import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import {
FiPlus,
FiEdit2,
FiTrash2,
FiCalendar,
FiMapPin,
FiImage,
FiUploadCloud,
FiX,
} from 'react-icons/fi';

import api, { getApiErrorMessage } from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import { useLanguage } from '../../contexts/LanguageContext';

const AdminEvents = () => {
const { t, language } = useLanguage();

const [events, setEvents] = useState([]);
const [loading, setLoading] = useState(true);
const [modalOpen, setModalOpen] = useState(false);
const [editingEvent, setEditingEvent] = useState(null);
const [submitting, setSubmitting] = useState(false);

const [formData, setFormData] = useState({
title_en: '',
title_km: '',
description_en: '',
description_km: '',
location_en: '',
location_km: '',
date: '',
is_upcoming: true,
is_past: false,
});

const [imageFile, setImageFile] = useState(null);
const [imagePreview, setImagePreview] = useState('');

useEffect(() => {
fetchEvents();
}, []);

const fetchEvents = async () => {
try {
setLoading(true);

  const response = await api.get('/api/events/');

  setEvents(
    Array.isArray(response.data)
      ? response.data
      : []
  );
} catch (error) {
  console.error('Error loading events:', error);

  toast.error(
    getApiErrorMessage(
      error,
      t('events.loadFailed')
    )
  );
} finally {
  setLoading(false);
}

};

const toDateInput = (value) => {
if (!value) {
return '';
}

return String(value).split('T')[0];

};

const formatDate = (value) => {
if (!value) {
return '-';
}

const dateOnly = String(value).split('T')[0];
const parts = dateOnly.split('-');

if (parts.length !== 3) {
  return '-';
}

const [year, month, day] = parts;

if (!year || !month || !day) {
  return '-';
}

const date = new Date(
  Number(year),
  Number(month) - 1,
  Number(day)
);

if (Number.isNaN(date.getTime())) {
  return '-';
}

return date.toLocaleDateString(
  language === 'km' ? 'km-KH' : 'en-GB',
  {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  }
);

};

const getEventTitle = (event) => {
if (language === 'km') {
return event?.title_km || event?.title_en || '-';
}

return event?.title_en || event?.title_km || '-';

};

const getEventLocation = (event) => {
if (language === 'km') {
return event?.location_km || event?.location_en || '';
}

return event?.location_en || event?.location_km || '';

};

const resetForm = () => {
setEditingEvent(null);

setFormData({
  title_en: '',
  title_km: '',
  description_en: '',
  description_km: '',
  location_en: '',
  location_km: '',
  date: '',
  is_upcoming: true,
  is_past: false,
});

if (
  imagePreview &&
  imagePreview.startsWith('blob:')
) {
  URL.revokeObjectURL(imagePreview);
}

setImageFile(null);
setImagePreview('');

};

const handleAdd = () => {
resetForm();
setModalOpen(true);
};

const handleCloseModal = () => {
setModalOpen(false);
resetForm();
};

const handleChange = (e) => {
const { name, value } = e.target;

setFormData((prev) => ({
  ...prev,
  [name]: value,
}));

};

const handleImageChange = (e) => {
const file = e.target.files?.[0];

if (!file) {
  return;
}

const allowedTypes = [
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/webp',
];

if (!allowedTypes.includes(file.type)) {
  toast.error(
    t('events.selectImage') ||
      'Please select JPG, JPEG, PNG or WEBP image.'
  );

  e.target.value = '';
  return;
}

const maxFileSize = 5 * 1024 * 1024;

if (file.size > maxFileSize) {
  toast.error('Image must be 5 MB or smaller.');

  e.target.value = '';
  return;
}

if (
  imagePreview &&
  imagePreview.startsWith('blob:')
) {
  URL.revokeObjectURL(imagePreview);
}

setImageFile(file);
setImagePreview(URL.createObjectURL(file));

};

const removeSelectedImage = () => {
if (
imagePreview &&
imagePreview.startsWith('blob:')
) {
URL.revokeObjectURL(imagePreview);
}

setImageFile(null);

if (editingEvent?.image) {
  setImagePreview(editingEvent.image);
} else {
  setImagePreview('');
}

};

const handleSubmit = async (e) => {
e.preventDefault();

if (!formData.title_en.trim()) {
  toast.error(
    t('events.titleRequired') ||
      'English title is required.'
  );
  return;
}

if (!formData.title_km.trim()) {
  toast.error(
    t('events.khmerTitleRequired') ||
      'Khmer title is required.'
  );
  return;
}

if (!formData.date) {
  toast.error(
    t('events.dateRequired') ||
      'Event date is required.'
  );
  return;
}

if (
  !/^\d{4}-\d{2}-\d{2}$/.test(
    formData.date
  )
) {
  toast.error(
    t('events.invalidDate') ||
      'Invalid event date.'
  );
  return;
}

try {
  setSubmitting(true);

  const payload = new FormData();

  payload.append(
    'title_en',
    formData.title_en.trim()
  );

  payload.append(
    'title_km',
    formData.title_km.trim()
  );

  payload.append(
    'description_en',
    formData.description_en.trim()
  );

  payload.append(
    'description_km',
    formData.description_km.trim()
  );

  payload.append(
    'location_en',
    formData.location_en.trim()
  );

  payload.append(
    'location_km',
    formData.location_km.trim()
  );

  payload.append(
    'date',
    formData.date
  );

  payload.append(
    'is_upcoming',
    String(formData.is_upcoming)
  );

  payload.append(
    'is_past',
    String(formData.is_past)
  );

  if (imageFile) {
    payload.append(
      'image_file',
      imageFile
    );
  }

  if (editingEvent) {
    await api.put(
      `/api/events/${editingEvent.id}`,
      payload
    );

    toast.success(
      t('events.updatedSuccess') ||
        'Event updated successfully.'
    );
  } else {
    await api.post(
      '/api/events/',
      payload
    );

    toast.success(
      t('events.createdSuccess') ||
        'Event created successfully.'
    );
  }

  handleCloseModal();
  await fetchEvents();
} catch (error) {
  console.error(
    'Event operation error:',
    error
  );

  toast.error(
    getApiErrorMessage(
      error,
      t('common.operationFailed')
    )
  );
} finally {
  setSubmitting(false);
}

};

const handleEdit = (event) => {
setEditingEvent(event);

setFormData({
  title_en: event.title_en || '',
  title_km: event.title_km || '',
  description_en: event.description_en || '',
  description_km: event.description_km || '',
  location_en: event.location_en || '',
  location_km: event.location_km || '',
  date: toDateInput(event.date),
  is_upcoming: Boolean(event.is_upcoming),
  is_past: Boolean(event.is_past),
});

setImageFile(null);
setImagePreview(event.image || '');
setModalOpen(true);

};

const handleDelete = async (id) => {
const confirmed = window.confirm(
t('events.deleteConfirm') ||
'Are you sure you want to delete this event?'
);

if (!confirmed) {
  return;
}

try {
  await api.delete(
    `/api/events/${id}`
  );

  toast.success(
    t('events.deletedSuccess') ||
      'Event deleted successfully.'
  );

  await fetchEvents();
} catch (error) {
  console.error(
    'Delete event error:',
    error
  );

  toast.error(
    getApiErrorMessage(
      error,
      t('events.deleteFailed')
    )
  );
}

};

const columns = [
{
key: 'title',
label: t('events.eventColumn'),
render: (_, row) => (
<div className="min-w-[180px]">
<p className="text-sm font-semibold text-blue-900">
{getEventTitle(row)}
</p>

      {row?.title_en && row?.title_km && (
        <p className="text-xs text-blue-300 mt-1">
          {language === 'km'
            ? row.title_en
            : row.title_km}
        </p>
      )}
    </div>
  ),
},
{
  key: 'date',
  label: t('common.date'),
  render: (value) => (
    <div className="flex items-center gap-2 text-sm text-blue-500 whitespace-nowrap">
      <FiCalendar
        className="text-red-600 flex-shrink-0"
        size={15}
      />

      <span>
        {formatDate(value)}
      </span>
    </div>
  ),
},
{
  key: 'location',
  label: t('common.location'),
  render: (_, row) => (
    <div className="flex items-center gap-2 text-sm text-blue-500 min-w-[150px]">
      <FiMapPin
        className="text-blue-900 flex-shrink-0"
        size={15}
      />

      <span className="truncate">
        {getEventLocation(row) ||
          t('common.notSpecified')}
      </span>
    </div>
  ),
},
{
  key: 'is_upcoming',
  label: t('common.status'),
  render: (value, row) => {
    const upcoming =
      Boolean(value) &&
      !row?.is_past;

    return (
      <span
        className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold ${
          upcoming
            ? 'bg-blue-50 text-blue-700 border border-blue-200'
            : 'bg-red-50 text-red-600 border border-red-100'
        }`}
      >
        <span
          className={`w-1.5 h-1.5 rounded-full ${
            upcoming
              ? 'bg-blue-500'
              : 'bg-red-500'
          }`}
        />

        {upcoming
          ? t('events.upcoming')
          : t('events.past')}
      </span>
    );
  },
},
{
  key: 'actions',
  label: t('common.actions'),
  render: (_, row) => (
    <div className="flex items-center gap-2">
      <button
        type="button"
        onClick={() => handleEdit(row)}
        className="w-8 h-8 flex items-center justify-center bg-blue-50 text-blue-900 rounded-lg hover:bg-blue-900 hover:text-white transition-all duration-200"
        title={t('common.edit')}
      >
        <FiEdit2 size={14} />
      </button>

      <button
        type="button"
        onClick={() => handleDelete(row.id)}
        className="w-8 h-8 flex items-center justify-center bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all duration-200"
        title={t('common.delete')}
      >
        <FiTrash2 size={14} />
      </button>
    </div>
  ),
},

];

const upcomingCount = events.filter(
(event) =>
event.is_upcoming &&
!event.is_past
).length;

const pastCount = events.filter(
(event) => event.is_past
).length;

return (
<div className="w-full">
<div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
<div className="flex items-center gap-3">
<div className="w-10 h-10 bg-blue-900 text-white rounded-xl flex items-center justify-center shadow-sm">
<FiCalendar size={18} />
</div>

      <div>
        <h1 className="text-xl md:text-2xl font-bold text-blue-900">
          {t('events.management')}
        </h1>

        <p className="text-xs md:text-sm text-blue-400 mt-1">
          {t('events.subtitle')}
        </p>
      </div>
    </div>

    <button
      type="button"
      onClick={handleAdd}
      className="h-10 px-4 inline-flex items-center justify-center gap-2 bg-red-600 text-white rounded-lg text-sm font-semibold shadow-sm hover:bg-red-700 hover:shadow-md transition-all duration-200"
    >
      <FiPlus size={17} />
      {t('events.addEvent')}
    </button>
  </div>

  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-5">
    <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">
      <p className="text-xs text-blue-400">
        {t('events.totalEvents')}
      </p>

      <p className="text-2xl font-bold text-blue-900 mt-1">
        {events.length}
      </p>
    </div>

    <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">
      <p className="text-xs text-blue-400">
        {t('events.upcoming')}
      </p>

      <p className="text-2xl font-bold text-blue-600 mt-1">
        {upcomingCount}
      </p>
    </div>

    <div className="bg-white border border-red-100 rounded-xl p-4 shadow-sm">
      <p className="text-xs text-blue-400">
        {t('events.pastEvents')}
      </p>

      <p className="text-2xl font-bold text-red-600 mt-1">
        {pastCount}
      </p>
    </div>
  </div>

  <AdminCard className="overflow-hidden border border-blue-200 shadow-sm rounded-xl">
    <div className="px-5 py-4 border-b border-blue-200 flex items-center justify-between">
      <div>
        <h2 className="text-sm font-bold text-blue-900">
          {t('events.allEvents')}
        </h2>

        <p className="text-xs text-blue-300 mt-1">
          {events.length}{' '}
          {events.length === 1
            ? t('events.event')
            : t('events.events')}{' '}
          {t('events.found')}
        </p>
      </div>
    </div>

    <AdminTable
      columns={columns}
      data={events}
      loading={loading}
    />
  </AdminCard>

  <AdminModal
    isOpen={modalOpen}
    onClose={handleCloseModal}
    title={
      editingEvent
        ? t('events.editEvent')
        : t('events.createEvent')
    }
  >
    <form onSubmit={handleSubmit}>
      <div className="space-y-5">
        <div className="p-4 bg-blue-50/50 border border-blue-100 rounded-xl">
          <div className="flex items-center gap-2 mb-4">
            <span className="inline-flex items-center justify-center px-2.5 py-1 rounded-md bg-blue-900 text-white text-xs font-bold">
              EN
            </span>

            <h3 className="text-sm font-bold text-blue-900">
              English Content
            </h3>
          </div>

          <div className="space-y-4">
            <div>
              <label className="admin-label">
                Event Title (English)
                <span className="text-red-600"> *</span>
              </label>

              <input
                type="text"
                name="title_en"
                value={formData.title_en}
                onChange={handleChange}
                placeholder="Enter event title in English"
                className="admin-input"
                required
              />
            </div>

            <div>
              <label className="admin-label">
                Description (English)
              </label>

              <textarea
                name="description_en"
                value={formData.description_en}
                onChange={handleChange}
                rows="3"
                placeholder="Enter event description in English"
                className="admin-input resize-none"
              />
            </div>

            <div>
              <label className="admin-label">
                Location (English)
              </label>

              <div className="relative">
                <FiMapPin
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-blue-300"
                  size={15}
                />

                <input
                  type="text"
                  name="location_en"
                  value={formData.location_en}
                  onChange={handleChange}
                  placeholder="Enter event location in English"
                  className="admin-input pl-9"
                />
              </div>
            </div>
          </div>
        </div>

        <div className="p-4 bg-red-50/30 border border-red-100 rounded-xl font-khmer">
          <div className="flex items-center gap-2 mb-4">
            <span className="inline-flex items-center justify-center px-2.5 py-1 rounded-md bg-red-600 text-white text-xs font-bold">
              KH
            </span>

            <h3 className="text-sm font-bold text-blue-900">
              មាតិកាភាសាខ្មែរ
            </h3>
          </div>

          <div className="space-y-4">
            <div>
              <label className="admin-label">
                ចំណងជើងព្រឹត្តិការណ៍
                <span className="text-red-600"> *</span>
              </label>

              <input
                type="text"
                name="title_km"
                value={formData.title_km}
                onChange={handleChange}
                placeholder="បញ្ចូលចំណងជើងព្រឹត្តិការណ៍ជាភាសាខ្មែរ"
                className="admin-input font-khmer"
                required
              />
            </div>

            <div>
              <label className="admin-label">
                សេចក្តីពិពណ៌នា
              </label>

              <textarea
                name="description_km"
                value={formData.description_km}
                onChange={handleChange}
                rows="3"
                placeholder="បញ្ចូលសេចក្តីពិពណ៌នាជាភាសាខ្មែរ"
                className="admin-input resize-none font-khmer"
              />
            </div>

            <div>
              <label className="admin-label">
                ទីតាំង
              </label>

              <div className="relative">
                <FiMapPin
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-blue-300"
                  size={15}
                />

                <input
                  type="text"
                  name="location_km"
                  value={formData.location_km}
                  onChange={handleChange}
                  placeholder="បញ្ចូលទីតាំងជាភាសាខ្មែរ"
                  className="admin-input pl-9 font-khmer"
                />
              </div>
            </div>
          </div>
        </div>

        <div>
          <label className="admin-label">
            {t('events.eventDate')}
            <span className="text-red-600"> *</span>
          </label>

          <input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            className="admin-input"
            required
          />
        </div>

        <div>
          <label className="admin-label">
            {editingEvent
              ? t('events.changeEventImage')
              : t('events.eventImage')}
          </label>

          {!imagePreview ? (
            <label className="min-h-[130px] border-2 border-dashed border-blue-200 rounded-xl flex flex-col items-center justify-center cursor-pointer bg-blue-50 hover:border-blue-400 transition-all">
              <FiUploadCloud
                size={27}
                className="text-blue-900 mb-2"
              />

              <p className="text-sm font-semibold text-blue-900">
                {t('events.clickUpload')}
              </p>

              <p className="text-[11px] text-blue-300 mt-1">
                JPG, JPEG, PNG, WEBP — Max 5 MB
              </p>

              <input
                type="file"
                accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"
                onChange={handleImageChange}
                className="hidden"
              />
            </label>
          ) : (
            <div className="relative w-full h-[180px] rounded-xl overflow-hidden bg-blue-50 border border-blue-200">
              <img
                src={imagePreview}
                alt={getEventTitle(editingEvent) || 'Event'}
                className="w-full h-full object-cover"
              />

              <button
                type="button"
                onClick={removeSelectedImage}
                className="absolute top-2 right-2 w-8 h-8 bg-black/60 text-white rounded-full flex items-center justify-center hover:bg-red-600 transition"
                title={t('common.remove')}
              >
                <FiX size={15} />
              </button>

              <label className="absolute left-3 bottom-3 inline-flex items-center gap-2 px-3 py-2 bg-white text-blue-900 rounded-lg text-xs font-semibold shadow-md cursor-pointer hover:bg-blue-900 hover:text-white transition">
                <FiImage />
                {t('events.changeImage')}

                <input
                  type="file"
                  accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"
                  onChange={handleImageChange}
                  className="hidden"
                />
              </label>
            </div>
          )}

          {editingEvent && !imageFile && imagePreview && (
            <p className="text-[11px] text-blue-300 mt-1.5">
              {t('events.keepCurrentImage')}
            </p>
          )}
        </div>

        <div>
          <label className="admin-label">
            {t('events.eventStatus')}
          </label>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <label
              className={`cursor-pointer flex items-center gap-3 p-3 rounded-xl border transition-all ${
                formData.is_upcoming
                  ? 'border-blue-300 bg-blue-50'
                  : 'border-blue-200 bg-white'
              }`}
            >
              <input
                type="checkbox"
                checked={formData.is_upcoming}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    is_upcoming: e.target.checked,
                    is_past: e.target.checked
                      ? false
                      : prev.is_past,
                  }))
                }
                className="w-4 h-4 accent-blue-600"
              />

              <div>
                <p className="text-sm font-semibold text-blue-900">
                  {t('events.upcoming')}
                </p>

                <p className="text-[10px] text-blue-300">
                  {t('events.futureEvent')}
                </p>
              </div>
            </label>

            <label
              className={`cursor-pointer flex items-center gap-3 p-3 rounded-xl border transition-all ${
                formData.is_past
                  ? 'border-red-300 bg-red-50'
                  : 'border-blue-200 bg-white'
              }`}
            >
              <input
                type="checkbox"
                checked={formData.is_past}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    is_past: e.target.checked,
                    is_upcoming: e.target.checked
                      ? false
                      : prev.is_upcoming,
                  }))
                }
                className="w-4 h-4 accent-red-600"
              />

              <div>
                <p className="text-sm font-semibold text-blue-900">
                  {t('events.past')}
                </p>

                <p className="text-[10px] text-blue-300">
                  {t('events.completedEvent')}
                </p>
              </div>
            </label>
          </div>
        </div>
      </div>

      <div className="mt-6 pt-4 border-t border-blue-200 flex items-center justify-end gap-3">
        <button
          type="button"
          onClick={handleCloseModal}
          disabled={submitting}
          className="h-10 px-4 border border-blue-200 bg-white text-blue-400 rounded-lg text-sm font-semibold hover:bg-blue-50 disabled:opacity-50 disabled:cursor-not-allowed transition"
        >
          {t('common.cancel')}
        </button>

        <button
          type="submit"
          disabled={submitting}
          className="min-w-[120px] h-10 px-5 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
        >
          {submitting
            ? editingEvent
              ? t('events.updating')
              : t('events.creating')
            : editingEvent
            ? t('events.updateEvent')
            : t('events.createEvent')}
        </button>
      </div>
    </form>
  </AdminModal>
</div>

);
};

export default AdminEvents;
